/*
 * A321333  Compound sequence with a(n) = A319198(A278040(n)), for n >= 0.
 * https://oeis.org/A321333
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = n + 1 + 2 * (# of zeros among the first n terms of the
 *            Tribonacci word)
 * Range:     u8 n <= 60, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The Tribonacci word is generated by the morphism 0→01, 1→02, 2→0. */
/* We maintain a cached word and its running zero count to compute a(n) in O(n) overall. */

#include <stdlib.h>

static unsigned char *tribo_word = NULL;   /* current Tribonacci word */
static seq_t *cum_zero = NULL;            /* cumulative zero counts */
static idx_t cur_len = 0;                 /* length of tribo_word */

/* Ensure the Tribonacci word has at least 'need' symbols (indices 0..need-1). */
static void ensure_len(idx_t need)
{
    if (need == 0)
        return;

    /* initialise if first call */
    if (!tribo_word) {
        tribo_word = /* word */ (unsigned char *)malloc(1);
        tribo_word[0] = 0;                    /* first symbol is 0 */
        cum_zero = (seq_t *)malloc(1 * sizeof(seq_t));
        cum_zero[0] = 1;                       /* first symbol is a zero */
        cur_len = 1;
    }

    while (cur_len < need) {
        /* compute new length after expanding each symbol */
        idx_t new_len = 0;
        for (idx_t i = 0; i < cur_len; ++i) {
            unsigned char v = tribo_word[i];
            new_len += (v == 0 || v == 1) ? 2 : 1;
        }

        /* allocate new structures */
        unsigned char *new_word = (unsigned char *)malloc((size_t)new_len);
        seq_t *new_cum = (seq_t *)malloc((size_t)new_len * sizeof(seq_t));

        /* expand and compute cumulative zeros on the fly */
        idx_t j = 0;
        seq_t running = 0;        /* zeros seen so far */
        for (idx_t i = 0; i < cur_len; ++i) {
            unsigned char v = tribo_word[i];
            if (v == 0) {          /* 0 → 0 1 */
                new_word[j] = 0;
                running += 1;          /* zero added */
                new_cum[j] = running;
                ++j;
                new_word[j] = 1;
                new_cum[j] = running;
                ++j;
            } else if (v == 1) {   /* 1 → 0 2 */
                new_word[j] = 0;
                running += 1;
                new_cum[j] = running;
                ++j;
                new_word[j] = 2;
                new_cum[j] = running;
                ++j;
            } else {               /* 2 → 0 */
                new_word[j] = 0;
                running += 1;
                new_cum[j] = running;
                ++j;
            }
        }

        /* replace old arrays */
        free(tribo_word);
        free(cum_zero);

        tribo_word = new_word;
        cum_zero  = new_cum;
        cur_len   = new_len;
    }
}

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;            /* a(0) = 1 */

    ensure_len(n);                 /* need symbols 0..n-1 */
    seq_t zeros = cum_zero[n - 1]; /* zeros among first n symbols */
    return (seq_t)n + (seq_t)1 + (seq_t)2 * zeros;
}
